{"connection_id": "BC-94e6d18b558c7397fad5", "ref": "SBLGNT:Matt.12.36", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "even idle words accounted", "note": "The commentary says tiny deeds are seen and every work is present; Jesus says people answer on judgment day for every careless word, extending accountability to speech."}
{"connection_id": "BC-c42d736d934998acbf2e", "ref": "SBLGNT:Matt.12.36", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "every idle word accounted for", "note": "Jesus says people will give account on judgment day even for careless speech; this gives the commentary's tiny measured deed a speech-sized counterpart."}
{"connection_id": "BC-3688ab519a57de7ad6c4", "ref": "SBLGNT:Matt.12.37", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "words justify or condemn", "note": "Jesus adds that one's own words will justify or condemn; this gives the commentary's exact accounting an explicit verdict for the small speech acts named in the preceding verse."}
{"connection_id": "BC-1440c428900c2621a8de", "ref": "SBLGNT:Matt.13.49", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "end-of-age separation", "note": "The commentary says good and evil are distinguished at the end; Jesus' net parable has angels separate the wicked from the righteous at the close of the age."}
{"connection_id": "BC-fe4f380413ed3e438828", "ref": "SBLGNT:Matt.13.49", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "angels separate wicked from righteous", "note": "Jesus describes angels separating evil people from righteous at the end of the age; this is a direct counterpart to the commentary's end-time distinction between bad and good."}
{"connection_id": "BC-f5d71980dd4df5966226", "ref": "SBLGNT:Matt.13.50", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "evil cast into the fiery furnace", "note": "The commentary associates evil work with punishment by fire; the net parable ends with the wicked thrown into a fiery furnace, giving separation a specific punitive outcome."}

