{"connection_id": "BC-3b9e4f1dd53f31a938cb", "ref": "SBLGNT:Rev.22.12", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "return; recompense; work", "note": "The commentary joins the appointed end to recompense for each person's work; the returning Christ says he brings reward to repay each according to work."}
{"connection_id": "BC-1f93ed0ce446b9cd9f5d", "ref": "SBLGNT:Rev.22.12", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "coming soon with recompense", "note": "The coming speaker brings recompense to repay everyone for what each has done; this links the commentary's approaching appointed day to personal reward."}
{"connection_id": "BC-28af0f63cfbadfdc844f", "ref": "SBLGNT:Rev.3.17", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "imagined wealth conceals poverty", "note": "The Laodiceans claim to need nothing but are called poor and exposed; this supplies the commentary's self-mistaken assessment with a striking deficit image."}
{"connection_id": "BC-0cbe83849f1ecc58eea0", "ref": "SBLGNT:Rev.3.2", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "works found incomplete", "note": "The risen speaker tells Sardis that its works have not been found complete before God; this is a precise counterpart to the commentary's apparently good work that fails the final assessment."}
{"connection_id": "BC-5c3e45e193b288b53dd2", "ref": "SBLGNT:Rom.14.12", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "each gives account to God", "note": "The commentary brings each person to a personal reckoning; Paul says each of us will give an account of himself to God, stressing individual answerability within a dispute about judging fellow believers."}
