item.stdout:
{"connection_id": "BC-f550640b69c33983d71d", "ref": "SBLGNT:Rom.2.7", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "persistent good work and life", "note": "Paul assigns eternal life to those who persist in doing good; this combines the commentary's good deeds, patient endurance, and exception from loss."}
{"connection_id": "BC-c59897fd463ff3fbd891", "ref": "SBLGNT:Rom.2.8", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "persisting against truth brings wrath", "note": "The commentary warns that persistence can be directed toward deeds of fire; Paul contrasts the good-work endurance with self-seeking disobedience to truth, which meets wrath, preserving the moral direction of perseverance."}
{"connection_id": "BC-560cace30657166de90f", "ref": "SBLGNT:Rom.2.8", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "disobey truth and receive wrath", "note": "Paul contrasts those who reject truth and follow wrongdoing with the patient doers of good, assigning wrath; this connects the commentary's communicated truth and bad works to its final division."}
{"connection_id": "BC-cb164d88bdda7af27d87", "ref": "Shepherd of Hermas, Mandate 5", "target": "sec13", "tradition": "incil", "kind": "motif", "basis": "patience as a practice of righteousness", "note": "The commentary makes patience part of the work that marks the exception; Hermas contrasts patience with short temper and connects endurance to right conduct, treating patience as morally active rather than passive delay."}
{"connection_id": "BC-f2a0df47218ce38de6ee", "ref": "1 Enoch 41:1", "target": "sec13", "tradition": "tevrat", "kind": "motif", "basis": "actions weighed in a balance", "note": "The commentary's scales weigh human deeds; 1 Enoch's heavenly vision explicitly includes the actions of people being weighed in a balance, extending the image into an apocalyptic tour of heaven."}
{"connection_id": "BC-14af4c154b1e35d83903", "ref": "1 Enoch 47:3", "target": "sec13", "tradition": "tevrat", "kind": "yorum_gelenegi", "basis": "books of the living opened", "note": "The apocalyptic court opens books of the living before the divine presence; this develops the commentary's record-and-day scene, though the books concern those counted as living rather than a list of every act."}
{"connection_id": "BC-483071361a8da86ecc89", "ref": "2 Baruch 24:1", "target": "sec13", "tradition": "tevrat", "kind": "yorum_gelenegi", "basis": "books of sins and stored righteousness", "note": "The apocalypse places written sins beside treasuries of righteous deeds when judgment arrives; this develops the commentary's present records and divided good and bad acts into two kinds of stored evidence."}
{"connection_id": "BC-db62f05593674b638e0e", "ref": "4 Ezra (2 Esdras) 7:33", "target": "sec13", "tradition": "tevrat", "kind": "motif", "basis": "seat of judgment; patience ends", "note": "The commentary describes a due day that closes the account; 4 Ezra says the Most High appears at the seat of judgment as compassion and long-suffering pass away, giving the end a sharper finality."}
{"connection_id": "BC-8b8debfa5ccc1ba877c7", "ref": "4 Ezra (2 Esdras) 7:35", "target": "sec13", "tradition": "tevrat", "kind": "yorum_gelenegi", "basis": "judgment, truth, recompense, awakened deeds", "note": "The commentary joins truth, work, and final recompense; 4 Ezra's end-time vision says judgment remains, truth stands, reward is shown, and good and evil deeds awaken, making the moral record explicit at the end."}
{"connection_id": "BC-73fec80bdb82588aed38", "ref": "4 Ezra 7:35", "target": "sec13", "tradition": "tevrat", "kind": "yorum_gelenegi", "basis": "works follow and deeds awake", "note": "The apocalyptic description says works follow, reward appears, good deeds awaken, and wicked deeds do not sleep; this gives the commentary's acts found present at judgment a vivid independent formulation."}
{"connection_id": "BC-a07be5e6e97360ece587", "ref": "Arakhin 16b", "target": "sec13", "tradition": "tevrat", "kind": "yorum_gelenegi", "basis": "limits and difficulty of rebuke", "note": "The commentary's mutual counsel in truth recalls Leviticus' command to rebuke a neighbor; the rabbis debate whether people know how to give or receive rebuke, showing how the duty can fail in practice."}
{"connection_id": "BC-5a34ebcab42f1a6c6f5f", "ref": "Babylonian Talmud Kiddushin 40b", "target": "sec13", "tradition": "tevrat", "kind": "yorum_gelenegi", "basis": "one deed tips the balance", "note": "The discussion urges a person to imagine oneself and the world balanced between merit and liability so one deed can tip the outcome; this interprets the commentary's minute weighed acts as morally consequential."}
{"connection_id": "BC-881e2303d9c56579d658", "ref": "Babylonian Talmud Rosh Hashanah 16b", "target": "sec13", "tradition": "tevrat", "kind": "yorum_gelenegi", "basis": "books for righteous and wicked", "note": "The Talmud speaks of books opened for the righteous, wicked, and intermediate at the new year; this gives the commentary's present deeds and good/bad division a specific Jewish record tradition."}
{"connection_id": "BC-bf7363965fbd5e8e0d66", "ref": "Kiddushin 40b", "target": "sec13", "tradition": "tevrat", "kind": "motif", "basis": "one deed tips the scales", "note": "The commentary says not even a small deed escapes the balance; Kiddushin teaches that a person should see himself and the world as balanced, since one commandment can tip both toward merit and one transgression toward guilt."}
{"connection_id": "BC-3b9ad8c02ed551ec5a3e", "ref": "Mishnah Avot 2:1", "target": "sec13", "tradition": "tevrat", "kind": "motif", "basis": "weigh commandment, reward, transgression, loss", "note": "The commentary makes work a moral account of gain and loss; Avot tells a person to weigh a commandment's loss against its reward and a transgression's reward against its loss, then says deeds are recorded in a book."}
{"connection_id": "BC-91336e198bbb52cc632e", "ref": "Mishnah Avot 2:1", "target": "sec13", "tradition": "tevrat", "kind": "yorum_gelenegi", "basis": "calculate deed's cost against reward", "note": "Avot urges calculating a commandment's loss against its reward and a sin's gain against its loss; this gives the commentary's profit-and-deficit language an explicit moral ledger tradition."}
{"connection_id": "BC-9bfe76d233b056a2ced0", "ref": "Mishnah Avot 3:15", "target": "sec13", "tradition": "tevrat", "kind": "motif", "basis": "world judged; preponderance of deeds", "note": "The commentary's account ends by sorting people according to their work; Avot says the world is judged with goodness and everything depends on the preponderance of deeds, a rabbinic formulation that makes action's cumulative weight explicit."}
{"connection_id": "BC-de46c62e69394308f418", "ref": "Mishnah Avot 3:16", "target": "sec13", "tradition": "tevrat", "kind": "yorum_gelenegi", "basis": "open ledger and exact collection", "note": "Avot describes an open ledger, a writing hand, collectors, and a true judgment of all actions; this supplies a detailed account metaphor for the commentary's closing of each person's record."}
{"connection_id": "BC-6046deb0cae7df6fd137", "ref": "Mishnah Avot 4:11", "target": "sec13", "tradition": "tevrat", "kind": "yorum_gelenegi", "basis": "deed creates advocate or accuser", "note": "Avot says one commandment gains an advocate and one transgression an accuser; this personifies the commentary's good and bad acts standing ready when judged."}
{"connection_id": "BC-60e34c7ef19216c30ded", "ref": "Mishnah Avot 4:22", "target": "sec13", "tradition": "tevrat", "kind": "motif", "basis": "life ends in an account before the King", "note": "The commentary brings each human to the term of an account; Avot says every person is born, lives, dies, and must give account before the King of kings, compressing life's whole course into an unavoidable reckoning."}

