text(await tools.apply_patch("*** Begin Patch
*** Update File: /Volumes/aro/projects/prose_generation/enrichment/bible/work/s103/ehlikitap-images.sol.max.s103-20261009/sec13/verdicts.jsonl
@@
 {"connection_id":"BC-420021d518a5c64951f6","ref":"WLC:Ps.62.13","status":"rejected","reason":"The psalm states personal work-based recompense but does not join it to an end-time deed scale; Romans 2:6-8 treats the same rule and alternatives.","paragraphs":[36],"evidence":["WLC:Ps.62.13"],"annotations":[]}
+{"connection_id":"BC-9ad05ad3f93fc53573e9","ref":"WLC:Ps.73.17","status":"rejected","reason":"The psalmist understands the wicked's eventual end only on entering the sanctuary; this verse alone says nothing about their works being weighed or recorded.","paragraphs":[37],"evidence":["WLC:Ps.73.17"],"annotations":[]}
+{"connection_id":"BC-0b25dcdaded21e051c3f","ref":"WLC:Ps.90.12","status":"rejected","reason":"Numbering days leads to a wise heart, a mortality lesson rather than an appointed day of work judgment; Job 14:5 more explicitly fixes the human term.","paragraphs":[36],"evidence":["WLC:Ps.90.12"],"annotations":[]}
+{"connection_id":"BC-b4e1f68d9319fa86481c","ref":"WLC:Ps.90.12","status":"rejected","reason":"The petition for wisdom from numbered days does not itself say that deeds are later weighed; Job 14:5 gives the specific bound cited on this page.","paragraphs":[36],"evidence":["WLC:Ps.90.12"],"annotations":[]}
+{"connection_id":"BC-9daa1618fe33c6e3077c","ref":"WLC:Ps.90.8","status":"rejected","reason":"The psalm places secret sins before God's face, but this is a communal confession, not each person's complete good-and-bad ledger; Ecclesiastes 12:14 covers hidden acts in judgment.","paragraphs":[37],"evidence":["WLC:Ps.90.8"],"annotations":[]}
+{"connection_id":"BC-6e5dc034b2d3c7408395","ref":"WLC:Ps.90.8","status":"rejected","reason":"Hidden communal wrongs are exposed, but the verse lacks the final judicial classification and individual record of this paragraph.","paragraphs":[37],"evidence":["WLC:Ps.90.8"],"annotations":[]}
+{"connection_id":"BC-d7ee5ac358a78791a15e","ref":"WLC:Ps.98.9","status":"rejected","reason":"The Lord comes to judge the world and peoples equitably, but no individual's acts, balance, or record is mentioned; Ecclesiastes 3:17-12:14 is closer.","paragraphs":[37],"evidence":["WLC:Ps.98.9"],"annotations":[]}
+{"connection_id":"BC-20501a8a55e4527c18d4","ref":"WLC:Zech.8.16","status":"rejected","reason":"Truthful neighbor speech and truthful peaceful gate judgments are clear civic ethics, but no mutual patient exhortation or final book follows here; Malachi 3:16-18 joins speech to the record.","paragraphs":[37],"evidence":["WLC:Zech.8.16"],"annotations":[]}
+{"connection_id":"BC-a4298a768dbd2d48ae34","ref":"WLC:Zech.8.16","status":"rejected","reason":"The command to speak truth with a neighbor is strong, yet it is civic restoration rather than the page's speech-book-day sequence, for which Malachi 3:16-18 is more specific.","paragraphs":[37],"evidence":["WLC:Zech.8.16"],"annotations":[]}
+{"connection_id":"BC-289fe1c098ebddc70d85","ref":"WLC:Zeph.2.2","status":"accepted","reason":"Hebrew חֹק appears before the day of divine anger comes, giving חקק a prescribed-term context beside Job 14:5; the cognate link remains unverified.","paragraphs":[36],"evidence":["WLC:Job.14.5","WLC:Zeph.2.2"],"annotations":["S103-TEV-SYD-001"]}
+{"connection_id":"BC-d2204adab3c79776ac89","ref":"Wisdom of Solomon 3:1","status":"unavailable","reason":"Wisdom 3:1 is absent from the frozen local snapshot; the proposed righteous-souls claim cannot be verified in this run.","paragraphs":[37],"evidence":[],"annotations":[]}
+{"connection_id":"BC-08a26c1ccd4a7c1e9b52","ref":"Wisdom of Solomon 3:9","status":"unavailable","reason":"Wisdom 3:9 is absent from the frozen local snapshot; trust, truth, and mercy wording cannot be checked.","paragraphs":[37],"evidence":[],"annotations":[]}
+{"connection_id":"BC-f7cf6e7e2a319d1dac45","ref":"Wisdom of Solomon 5:1","status":"unavailable","reason":"Wisdom 5:1 is absent from the frozen local snapshot; the alleged vindication scene remains unverified.","paragraphs":[37],"evidence":[],"annotations":[]}
+{"connection_id":null,"origin":"research","ref":"CORPUSCORANICUM:103:1-3:kommentar","status":"rejected","reason":"Modern commentary weighs liturgical versus market-close readings of the oath; it is background interpretation, not an additional Jewish or Christian primary parallel for these annotations.","paragraphs":[36,37],"evidence":["CORPUSCORANICUM:103:1-3:kommentar"],"annotations":[]}
+{"connection_id":null,"origin":"research","ref":"CORPUSCORANICUM-INTERTEXT:103:2:178","status":"rejected","reason":"The catalogue entry points to Luke 9:23-27 and reports a Syriac cognate, but its Syriac witness is unavailable locally and the Greek verses were assessed independently.","paragraphs":[36],"evidence":["CORPUSCORANICUM-INTERTEXT:103:2:178"],"annotations":[]}
+{"connection_id":null,"origin":"research","ref":"CORPUSCORANICUM-INTERTEXT:103:2:179","status":"rejected","reason":"The catalogue entry calls Philippians 3:7-8 an eschatological loss parallel, but the opened Greek describes Paul's own revaluation of status for Christ; its Syriac wording is not locally checked.","paragraphs":[36],"evidence":["CORPUSCORANICUM-INTERTEXT:103:2:179"],"annotations":[]}
+{"connection_id":null,"origin":"research","ref":"SBLGNT:Luke.9.24","status":"rejected","reason":"Losing life for Jesus in discipleship is a save/lose paradox, not the section's deed-weighing or righteous-work account.","paragraphs":[36],"evidence":["SBLGNT:Luke.9.24"],"annotations":[]}
+{"connection_id":null,"origin":"research","ref":"SBLGNT:Luke.9.25","status":"rejected","reason":"World gain and self-loss are a close commercial contrast, yet this verse names no deeds or appointed weighing; Daniel 5:27 supplies the more specific scale-and-deficiency image.","paragraphs":[36],"evidence":["SBLGNT:Luke.9.25"],"annotations":[]}
+{"connection_id":null,"origin":"research","ref":"SBLGNT:Phil.3.7","status":"rejected","reason":"Paul voluntarily counts previous gains as loss for Christ, not a judge finding a person's deeds deficient; the proposed eschatological verdict would misread the Greek context.","paragraphs":[36],"evidence":["SBLGNT:Phil.3.7"],"annotations":[]}
+{"connection_id":null,"origin":"research","ref":"SBLGNT:Phil.3.8","status":"rejected","reason":"Paul regards all as loss so as to gain Christ, a first-person value reversal rather than the universal final account of the surah.","paragraphs":[36],"evidence":["SBLGNT:Phil.3.8"],"annotations":[]}
+{"connection_id":null,"origin":"research","ref":"SBLGNT:Rev.2.19","status":"rejected","reason":"Works, faith, service, and endurance appear together, but no due judgment or mutual truth counsel is stated; Romans 2:6-8 ties good-work endurance to a verdict.","paragraphs":[36],"evidence":["SBLGNT:Rev.2.19"],"annotations":[]}
+{"connection_id":null,"origin":"research","ref":"SBLGNT:Rom.2.2","status":"rejected","reason":"Judgment according to truth upon wrongdoers supports the nearby Romans passage but adds no specific work-and-patience distinction beyond 2:6-8.","paragraphs":[36],"evidence":["SBLGNT:Rom.2.2"],"annotations":[]}
+{"connection_id":null,"origin":"research","ref":"SBLGNT:Eph.2.8","status":"rejected","reason":"Grace through faith supplies context for 2:9; with 2:10 it prevents treating 'not from works' as a denial that believers do good work, but adds no page annotation.","paragraphs":[36],"evidence":["SBLGNT:Eph.2.8"],"annotations":[]}
*** End Patch"));

