+{"connection_id":"BC-203b9e552ba4279c36a7","ref":"SBLGNT:Rev.20.13","status":"accepted","reason":"Each returned dead person is judged according to works; 20:12 identifies the opened written books, and both are expressed in the annotation.","paragraphs":[37],"evidence":["SBLGNT:Rev.20.12","SBLGNT:Rev.20.13"],"annotations":["S103-INC-MTF-003"]}
